using UnityEngine;using UnityEditor;using System.Linq;using System.Collections.Generic;
public static class InspectVacuum {public static object Run(){var f=Selection.activeGameObject.transform.parent.Find("casing").GetComponent<MeshFilter>();var m=f.sharedMesh;var v=m.vertices;var t=m.triangles;var parent=Enumerable.Range(0,v.Length).ToArray();System.Func<int,int> find=null;find=i=>parent[i]==i?i:parent[i]=find(parent[i]);var weld=new Dictionary<Vector3,int>();for(int i=0;i<v.Length;i++){if(weld.TryGetValue(v[i],out var n))parent[find(i)]=find(n);else weld[v[i]]=i;}for(int i=0;i<t.Length;i+=3){parent[find(t[i+1])]=find(t[i]);parent[find(t[i+2])]=find(t[i]);}System.IO.File.WriteAllText("output/vacuum-mesh.json",Newtonsoft.Json.JsonConvert.SerializeObject(new {vertices=v.Select(p=>new[]{p.x,p.y,p.z}).ToArray(),triangles=t,groups=t.Distinct().ToDictionary(i=>i,i=>find(i))}));return new{hierarchy=f.transform.parent.name,groups=t.Distinct().GroupBy(i=>find(i)).Select(g=>{var b=new Bounds(v[g.First()],Vector3.zero);foreach(var i in g)b.Encapsulate(v[i]);return new{id=g.Key,count=g.Count(),center=b.center.ToString("F5"),size=b.size.ToString("F5")};}).ToArray()};}}

